import type { Page } from '@playwright/test';

import { settle } from '../scripts/a11y/settle';

/** Open a route and every tab on it, so the requests behind each tab are made. `route` is
 *  app-relative (`/suites/…`); it resolves under the project's baseURL, sub-path included. */
export async function visit(page: Page, route: string): Promise<void> {
  await page.goto(route.replace(/^\//, ''));
  await idle(page);
  const tabs = page.getByRole('tab');
  for (let i = 0; i < (await tabs.count()); i += 1) {
    const tab = tabs.nth(i);
    if (!(await tab.isVisible()) || (await tab.getAttribute('aria-disabled')) === 'true') continue;
    await tab.click();
    await idle(page);
  }
}

async function idle(page: Page): Promise<void> {
  // A polling page never goes network-idle for long; the spinner check below is the real gate.
  await page.waitForLoadState('networkidle', { timeout: 5_000 }).catch(() => undefined);
  await settle(page);
}
import { expect, type Page } from '@playwright/test';

/** Wait until the page has stopped loading. A route's landmark can be visible while a table
 * inside it is still behind its `loading` Spin, so the rows a scan should judge are not in the
 * DOM yet and the scan passes vacuously. Also lets mount transitions finish, which otherwise
 * get sampled mid-colour. */
export async function settle(page: Page): Promise<void> {
  await expect(page.locator('.ant-spin-spinning, .ant-skeleton-active')).toHaveCount(0);
  await page.evaluate(() =>
    Promise.all(
      document
        .getAnimations()
        .filter((a) => a.effect?.getComputedTiming().iterations !== Infinity)
        .map((a) => a.finished.catch(() => undefined)),
    ),
  );
}
import { expect, test } from '@playwright/test';
import { writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

import { fixtureKey, type FixtureBundle, type RecordedResponse } from '../src/demo/fixtures';
import { discoverRoutes } from './routes';
import { visit } from './visit';

// Records what the app asks the API for on every route of the seeded workspace (#2419). The
// output, demo-fixtures.json, is never committed: CI records it from the stack it just seeded.
const OUT = resolve(dirname(fileURLToPath(import.meta.url)), '../demo-fixtures.json');
const API = '/api/v1';

test('record the seeded workspace', async ({ page }) => {
  test.setTimeout(15 * 60_000);
  const entries: Record<string, RecordedResponse> = {};
  const failures: string[] = [];
  const pending: Promise<void>[] = [];

  page.on('response', (response) => {
    const url = new URL(response.url());
    if (!url.pathname.startsWith(`${API}/`) || response.request().method() !== 'GET') return;
    const key = fixtureKey('GET', url.pathname + url.search);
    if (response.status() >= 500) failures.push(`${response.status()} ${key}`);
    pending.push(
      (async () => {
        const all = response.headers();
        if (!(all['content-type'] ?? '').includes('json')) return;
        const headers = Object.fromEntries(
          Object.entries(all).filter(([k]) => k.startsWith('x-') && k !== 'x-request-id'),
        );
        // A response whose page navigated away before its body was read is recorded on the
        // page that waits for it; losing this copy is fine.
        const data: unknown = await response.json().catch(() => undefined);
        if (data === undefined) return;
        entries[key] = { status: response.status(), data, headers };
      })(),
    );
  });

  const routes = await discoverRoutes(async (path) => {
    const response = await page.request.get(`${API}${path}`);
    expect(response.ok(), `GET ${path}`).toBe(true);
    return response.json();
  });
  for (const route of routes) await visit(page, route);
  await Promise.all(pending);

  expect(failures, 'the API answered 5xx while recording').toEqual([]);
  expect(Object.keys(entries).length).toBeGreaterThan(routes.length / 2);
  const bundle: FixtureBundle = { capturedAt: new Date().toISOString(), routes, entries };
  writeFileSync(OUT, JSON.stringify(bundle));
  console.log(`recorded ${Object.keys(entries).length} responses over ${routes.length} routes`);
});
# Static demo lane

The read-only demo published at `/demo/` on the GitHub Pages site (#2419) is the real
frontend, built with `VITE_DEMO=true` so the API client answers from recorded responses
instead of a backend. Nothing here is committed output: CI records, builds and smoke-tests
it on every run of the `frontend-e2e` job, and a push to `main` publishes the result.

| Step   | Command             | What it does                                                                                                                                                                                     |
| ------ | ------------------- | ------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------ |
| Record | `pnpm demo:capture` | Visits every route in `routes.ts` (and each tab on it) against the seeded dev-bypass stack and writes the `GET /api/v1` responses to `demo-fixtures.json`.                                       |
| Build  | `pnpm demo:build`   | Builds the SPA for `DEMO_BASE` (default `/DataQ/demo/`) into `dist-demo/`, with the fixtures and a `config.js` that selects no-IdP mode.                                                         |
| Smoke  | `pnpm demo:smoke`   | Serves `marketing/` + `dist-demo/` the way GitHub Pages does (`pages-server.mjs`) and drives the built files: every route renders from the recording alone, deep links work, writes are refused. |

Locally, record against the docs capture stack so your own workspace is never the source:

```bash
scripts/docs/capture-stack.sh start
cd frontend
E2E_DEMO_BASE_URL=http://127.0.0.1:3001 pnpm demo:capture
pnpm demo:build && pnpm demo:smoke
```

## What keeps it from drifting

- **A new route** must be added to `ROUTE_PATTERNS` in `routes.ts`;
  `tests/demo/routeCoverage.test.ts` fails otherwise.
- **A new request on an existing route** is recorded automatically, because the recording is
  remade from the current code on every CI run.
- **A request the recording cannot answer** (a value that changes between record and replay,
  a call that bypasses the shared axios client, an absolute URL that ignores the base path)
  fails the smoke test.
- **Dates** in the recording are moved forward by whole days at replay, so the data reads as
  recent between publishes.

## What the demo does not do

Requests made only after a click that the crawl does not perform (a drawer, a filter, a
download) are not recorded. The demo says so in a notice instead of showing an empty or
wrong view. Every non-`GET` request is refused with a notice that links to the install
guide.

